pub const chat = "<!doctype html><meta charset=utf-8><title>mock</title><style>body{font:16px sans-serif}div[role=button],button{display:block;padding:8px;margin:4px;border:1px solid #888}#box{border:1px solid #444;min-height:30px;width:300px}</style><input aria-label='Tìm kiếm' id=q><div id=list role=list><div role=listitem aria-label='Mom unread 2' onclick=\"openChat('Mom')\">Mom</div><div role=listitem aria-label='Boss' onclick=\"openChat('Boss')\">Boss</div></div><div id=thread></div><div role=textbox contenteditable=true aria-label='Nhập @, tin nhắn tới' id=box></div><button aria-label='Gửi' onclick='sendMsg()'>Gửi</button><button aria-label='Ghim hội thoại' onclick='st.pin=ch'>pin</button><button aria-label='Tắt thông báo' onclick='st.mute=ch'>mute</button><button aria-label='Chuyển tiếp' onclick='st.fwd=ch'>fwd</button><button aria-label='Tạo nhóm' onclick='st.grp=1'>grp</button><button aria-label='Nhắc hẹn' onclick=\"rem.style.display='block'\">rem</button><div id=rem style='display:none'><input aria-label='Tiêu đề' id=rt><input aria-label='Thời gian' id=rw><button aria-label='Tạo' onclick='mkRem()'>ok</button></div><script>var sent=[],st={},ch='',rems=[],trust=[],moves=0,keys=0;var D={Mom:['them|Hi son','them|Dinner at 7?'],Boss:['them|Report ready?']};function add(m){var p=m.split('|');var d=document.createElement('div');d.setAttribute('role','article');d.setAttribute('aria-label',(p[0]=='me'?'me: ':'')+p[1]);d.textContent=p[1];thread.appendChild(d)}function openChat(n){ch=n;thread.innerHTML='';(D[n]||[]).forEach(add)}function sendMsg(){var t=box.innerText.trim();if(!t)return;sent.push(ch+'|'+t);(D[ch]=D[ch]||[]).push('me|'+t);add('me|'+t);box.innerText=''}function mkRem(){rems.push(rt.value+'|'+rw.value)}document.addEventListener('click',function(e){trust.push(e.isTrusted)});document.addEventListener('mousemove',function(){moves++});document.addEventListener('keydown',function(){keys++});</script>";
